"""Merge sort implemented from scratch, timed on the shared dataset."""
import json
import os
import time


def _merge(left, right):
    merged = []
    i = j = 0
    ln, rn = len(left), len(right)
    while i < ln and j < rn:
        if left[i] <= right[j]:
            merged.append(left[i])
            i += 1
        else:
            merged.append(right[j])
            j += 1
    if i < ln:
        merged.extend(left[i:])
    if j < rn:
        merged.extend(right[j:])
    return merged


def sort(arr):
    """Return a new list with the elements of arr in ascending order (top-down merge sort)."""
    n = len(arr)
    if n <= 1:
        return list(arr)
    mid = n // 2
    return _merge(sort(arr[:mid]), sort(arr[mid:]))


if __name__ == "__main__":
    here = os.path.dirname(os.path.abspath(__file__))
    with open(os.path.join(here, "sort_dataset.json")) as f:
        data = json.load(f)

    best = float("inf")
    result = None
    for _ in range(5):
        copy = list(data)
        t0 = time.perf_counter()
        result = sort(copy)
        elapsed = (time.perf_counter() - t0) * 1000.0
        if elapsed < best:
            best = elapsed

    assert result == sorted(data), "merge sort output does not match sorted(data)"
    print("ALGO mergesort")
    print(f"BEST_MS {best:.3f}")
